// from src/locales/ja/blog.ts. Body + FAQs for article 'image-contrast-editor-guide' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>コントラストは、写真の最も暗い部分と最も明るい部分の違いです。コントラストが写真に力強さと深みを与えるか、平たくグレーに見せるかを決めます。</p>\n<p>コントラストのいい写真は、深い影と明るいハイライトがあり、奥行きがはっきり感じられます。コントラストの低い写真は、霧を通して撮ったようにかすんで見えます。</p>\n<p>この記事では、コントラストの仕組みとスライダーやプリセットの使い方、ハイライトを飛ばさず影を潰さずに力強さを足す方法を解説します。ポートレート、風景、スクリーンショット、よくある失敗までカバーします。スライダーとプリセットの感触は、<a href=\"/ja/kontrasuto-chosei/\">画像コントラストエディター</a>で実際の写真に触れて確かめられます。</p>\n<h2 id=\"what-contrast-does\">コントラストは何をするのか</h2>\n<p>コントラストは、画像の明暗の範囲を広げたり縮めたりします。上げると暗いピクセルはより暗く、明るいピクセルはより明るくなり、両端の差が広がります。</p>\n<p>下げると逆になります。暗い部分と明るい部分が近づき、画像がやわらかくなって、最も明るい部分と最も暗い部分の違いが小さくなります。</p>\n<p>コントラストは全体の明るさをあまり変えません。コントラストの高い写真は全体が暗くても明るくても、影とハイライトの差はどちらにしても大きくなります。</p>\n<p>コントラストは、ロープの両端の距離のようなものです。両端を引っ張ると明暗が広がり、近づけると真ん中に集まります。</p>\n<h2 id=\"why-photos-look-flat\">写真が平たく見える理由</h2>\n<p>かすみは、平たい写真の最も多い原因です。霧やもや、湿った空気が光を散らし、影を持ち上げてハイライトをくすませ、画像全体が中間に集まります。</p>\n<p>曇りの光も写真を平たくします。曇った空はやわらかく均一な光で、強い影がないので、画像には最初から明暗の幅がほとんどありません。</p>\n<p>スキャンした古い写真も平たく見えがちです。年月でプリントが色あせ、スキャナーが明暗を読み違えると、深い黒も明るい白もないグレーがかった画像になります。</p>\n<p>スマホのカメラも、暗い場所では平たい写真を撮ることがあります。センサーが明暗の全範囲をとらえきれず、画像が中間の明るさに圧縮されます。</p>\n<h2 id=\"slider-explained\">コントラストスライダーの使い方</h2>\n<p>コントラストスライダーはマイナスからプラスの値で動き、0が変化なしです。右に動かすとコントラストが上がり、左に動かすと下がります。</p>\n<p>小さな動きでも大きな違いが出ます。10〜20%の変化で平たい写真が直ることが多く、それ以上大きく動かすとハイライトがすぐ飛び、影がすぐ潰れます。</p>\n<p>このツールは、アップロード直後に写真を+20%でプレビューします。この出発点から、中くらいのコントラストの追加がどんな感じかすぐわかります。</p>\n<p>スライダーはゆっくりドラッグして、プレビューを見ましょう。ライブ表示で画像の反応がそのまま見えるので、ちょうどいいところで止められます。</p>\n<h2 id=\"quick-presets\">ワンクリックで直せるプリセット</h2>\n<p>ツールには、よく使うコントラストの値をワンクリックで適用できるプリセットがあります。スライダーをドラッグせずに、いろいろなレベルをすばやく試せます。</p>\n<p>プリセットは出発点であって、最終的な答えではありません。1つクリックしてプレビューを見て、近いけれど少し違うならスライダーで微調整します。</p>\n<p>プリセットは選択肢の比較にも便利です。+10%と+30%を比べれば、写真が飛ぶ前にどれだけコントラストを足せるかわかります。</p>\n<p>似た写真をまとめて処理するときは、同じプリセットで結果をそろえられます。かすんだ風景をすべて同じだけ追加すれば、シリーズのように見えます。</p>\n<h2 id=\"compare-modes\">比較モード：修正前・修正後・分割表示</h2>\n<p>比較モードでは、元の写真と編集後の写真をいっしょに見られます。「修正後」はコントラストを上げた画像、「修正前」は元の画像、「分割」は両方を並べた表示です。</p>\n<p>コントラストの作業では、分割比較がいちばん便利です。どの影が深くなり、どのハイライトが明るくなったかが、2つのバージョンの境目ではっきりわかります。</p>\n<p>フルスクリーン比較は、最も大きく見られる表示です。小さいプレビューでは隠れていた白飛びまで見えるので、コントラストの編集を判断するのに最適です。</p>\n<p>ダウンロード前には必ず比較表示を確認しましょう。さっと見るだけで、小さいプレビューでは隠れていた白飛びしたハイライトや潰れた影に気づけます。</p>\n<h2 id=\"contrast-and-colour\">コントラストと色の関係</h2>\n<p>コントラストは明暗だけでなく色にも影響します。コントラストを上げると色が濃く鮮やかになります。暗い部分がより暗く、明るい部分がより明るくなるからです。</p>\n<p>コントラストを下げると色がくすみます。コントラストの低いやわらかい画像は、穏やかなパステル調の色になり、ポートレートや夢のような風景に合います。</p>\n<p>つまり、コントラストの変更は色の変更でもあります。力強さがほしい写真はコントラスト、色の鮮やかさがほしい写真は彩度が合うかもしれません。</p>\n<p>色の調整だけをしたいときは、コントラストを決めたあとに<a href=\"/ja/saido-chosei/\">画像彩度調整ツール</a>を使います。2つの操作を組み合わせると、画像の見た目を完全にコントロールできます。</p>\n<h2 id=\"contrast-for-portraits\">ポートレートのコントラスト</h2>\n<p>ポートレートはやさしいコントラストが必要です。コントラストが強すぎる顔は、きつく老けて見え、目の下に深い影ができ、額に明るい斑点ができます。</p>\n<p>まず10%の小さな追加から始め、肌を確認します。顔ははっきり見えるべきで、影が描き込まれたようになってはいけません。</p>\n<p>マイナスのコントラストは、きついポートレートに役立ちます。真昼の太陽が顔に強い影を作るとき、小さな下げ幅で影をやわらげ、顔の形はそのまま残せます。</p>\n<p>やわらかい窓の光で撮ったポートレートは、コントラストがすでに合っていることが多いです。5〜10%の小さな追加で十分で、それ以上大きくすると害になります。</p>\n<h2 id=\"contrast-for-landscapes\">風景写真のコントラスト</h2>\n<p>風景写真はコントラストの効果が最も大きいです。かすんだ山、霧の谷、くすんだ空は、中くらいの追加で深みとドラマが出ます。</p>\n<p>かすんだ風景には15〜25%の追加を使います。影が深くなり、ハイライトが明るくなり、かすみが奪った力強さが戻ります。</p>\n<p>コントラストを上げながら、空を見ましょう。雲が先に飛び、形のない白い空白になります。白飛びした空は、せっかくのいい風景を台無しにします。</p>\n<p>空が明るく前景が暗い風景では、妥協を受け入れましょう。コントラストは両端をいっしょに広げるので、空と地面は反対方向に動きます。</p>\n<h2 id=\"contrast-for-screenshots\">スクリーンショット・書類のコントラスト</h2>\n<p>スクリーンショットやスキャンした書類は、読みやすさのためにコントラストが必要です。文字が背景から際立たなければならず、グレーの文字がのった低コントラストのスキャンは読みにくいです。</p>\n<p>スクリーンショットはCtrl+Vで直接貼り付けられます。保存する手間が省けて、すぐに調整できます。</p>\n<p>文字が暗く背景が白くなるまでコントラストを上げます。黒い文字がはっきりした白い背景の書類は、読みやすく印刷もしやすくなります。</p>\n<p>背景のノイズに注意しましょう。強くコントラストを上げたスキャンは、特に圧縮済みのJPEGでは、斑点や跡が見えることがあります。</p>\n<h2 id=\"negative-contrast\">マイナスのコントラスト：きつい写真をやわらげる</h2>\n<p>マイナスのコントラストは、暗い部分と明るい部分を近づけて画像をやわらげます。真昼の強い日差しで撮った写真に適しています。</p>\n<p>-10%や-20%のような値で、ポートレートの強い影をやわらげます。顔の形は残り、きつい縁がやさしい印象に変わります。</p>\n<p>マイナスのコントラストは、夢のようなやわらかい風景にも合います。霧の朝のシーンはコントラストが低いと穏やかで静かに感じられ、写真のムードと合います。</p>\n<p>やりすぎには注意しましょう。コントラストが少なすぎる写真は、晴れた日でも霧を通して撮ったようにグレーで生気がなく見えます。</p>\n<h2 id=\"clipping-and-crushing\">白飛びと黒潰れ</h2>\n<p>白飛びは、ハイライトが真っ白を超えて押し出されたときに起きます。明るい雲や白いシャツのディテールが消え、特徴のない空白になります。</p>\n<p>黒潰れは、シャドウが真っ黒を超えて押し出されたときに起きます。暗いコートや影のある隅のディテールが消え、真っ黒な斑点になります。</p>\n<p>どちらも、書き出したファイルでは元に戻りません。ディテールが飛んだり潰れたりしたら、あとの編集では取り戻せないので、ダウンロード前に両端を確認しましょう。</p>\n<p>白飛びと黒潰れを見つけるには比較表示を使います。分割表示では、どの部分がディテールを失ったかがはっきりわかり、スライダーを少し下げればたいてい戻ります。</p>\n<h2 id=\"formats-and-export\">ファイル形式と書き出し</h2>\n<p>このツールはJPG、PNG、WebP、HEICなどの一般的な画像形式に対応し、ファイルは最大20MBまで扱えます。書き出しはJPG、PNG、WebPから選べます。</p>\n<p>PNGやWebPで書き出すと、元画像の透明が保たれます。透明なPNGのグラフィックなら、コントラストを調整した書き出しでも透けた部分がそのまま残ります。</p>\n<p>写真には、高画質設定のJPGが合います。コントラストを上げてもファイルサイズはあまり増えないので、書き出しは元の重さに近いままです。</p>\n<p>画質スライダーはJPGとWebPの書き出しで表示され、PNGでは表示されません。PNGは可逆圧縮で画質設定がないためです。</p>\n<h2 id=\"contrast-vs-brightness\">コントラストと明るさ：どちらが先か</h2>\n<p>明るさは全体のレベルを決め、コントラストはその周りの幅を決めます。暗すぎる写真はまず明るさが必要です。コントラストではレベルは直りません。</p>\n<p>平たいけれど明るさが合っている写真は、コントラストだけで十分です。明るくすると、明るく平たくなるだけで、よくなりません。</p>\n<p>写真が両方を必要とするときは、明るさが先、コントラストがあとです。順番が大事なのは、明るさがコントラストの調整に必要なことを変えるからです。</p>\n<p>詳しい比較は、<a href=\"/ja/blog/akari-rosyutsu-kontrasuto-chigai/\">明るさ・露出・コントラストの違い</a>をご覧ください。</p>\n<h2 id=\"privacy-local-processing\">プライバシー：アップロードせずに編集する</h2>\n<p>コントラストの編集はすべてブラウザの中で行われます。写真がサーバーにアップロードされることはありません。家族写真や仕事の写真では、この点がとても重要です。</p>\n<p>クラウド型の編集ツールと比べて、これは大きな利点です。コントラストを足すためだけに、大切な写真を見知らぬサーバーに送る必要はありません。</p>\n<p>書き出すときに、EXIFの位置情報も取り除かれます。ツールからダウンロードしたコントラスト調整済みの写真には、撮影場所の記録が残りません。</p>\n<p>編集前の元写真は、必ず残しておきましょう。コントラストの変更を書き出すと元に戻せないので、元ファイルが唯一のきれいなコピーです。</p>\n<h2 id=\"common-mistakes\">コントラスト調整でよくある失敗</h2>\n<p>いちばん多い失敗は、コントラストを足しすぎることです。+50%以上まで上げると、ハイライトもシャドウも完全に失われ、きついポスターのような画像になります。</p>\n<p>次に多いのは、コントラストで暗い写真を直そうとすることです。コントラストの高い暗い写真は、影が深くなっただけでやはり暗く、被写体は隠れたままです。</p>\n<p>両端の確認を忘れる人も多いです。小さいプレビューではよく見えた空や影も、実物大では飛んだり潰れたりしていることがあるので、必ず大きくして確認します。</p>\n<p>同じJPGを繰り返し調整するのも避けましょう。保存するたびに劣化するので、コントラストを変えたいときは必ず元のファイルからやり直します。</p>\n<h2 id=\"contrast-workflow\">きれいに仕上げる作業の流れ</h2>\n<p>まず元のファイルを用意し、写真が平たいか、きついか、幅が合っているかを判断します。平たい写真は追加、きつい写真は下げ幅、合っている写真は何もしません。</p>\n<p>コントラストを適用してから、比較表示で確認します。分割表示では、どの影が深くなり、どのハイライトが明るくなったかがはっきりわかります。</p>\n<p>ハイライトとシャドウは別々に確認します。ハイライトは追加で先に飛び、シャドウは同じ動きで先に潰れるので、両端に注意が必要です。</p>\n<p>高画質設定で書き出し、実物大で結果を確認します。明るい部分と暗い部分にズームして、ディテールが失われていないか見ます。</p>\n<h2 id=\"contrast-for-black-white\">白黒写真のコントラスト</h2>\n<p>白黒写真はコントラストで決まります。色がない分、明暗の範囲がすべてで、平たい白黒写真はグレーで生気がなく見えます。</p>\n<p>白黒写真には、カラーより強めのコントラストを使います。20〜30%の追加で、深い黒と明るい白が出て、印象的な仕上がりになります。</p>\n<p>コントラストを上げながら、中間調を見ましょう。白黒のポートレートは肌に滑らかなグレーのトーンが必要で、コントラストが強すぎると顔がきつい白黒の斑点になります。</p>\n<p>白黒の風景では、コントラストが中心のツールです。山や空、前景は、はっきりした明暗の幅でディテールが出ます。</p>\n<p>手順をステップごとに知りたい方は、<a href=\"/ja/blog/kontrasuto-chosei-yarikata/\">画像のコントラスト調整のやり方</a>をご覧ください。比較記事は<a href=\"/ja/blog/akari-rosyutsu-kontrasuto-chigai/\">明るさ・露出・コントラストの違い</a>、暗い写真を先に直すなら<a href=\"/ja/gazou-akari-chosei/\">画像明るさ調整ツール</a>をお試しください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"平たい写真にはどれくらいコントラストを足せばいいですか？","answer":"まず10〜20%から始めて、プレビューを確認しましょう。ほとんどの平たい写真は小さな追加で十分で、大きく動かすとハイライトがすぐ飛び、シャドウがすぐ潰れます。少しずつ上げて、ディテールを失わずに画像がしっかり感じられる所で止めます。"},{"question":"コントラストを足したら写真がきつく見えるのはなぜですか？","answer":"コントラストを上げすぎたため、シャドウが深くなりすぎ、ハイライトが明るくなりすぎて、ディテールが残らなくなっています。スライダーを下げて、肌や空、影の部分に質感が戻るまで調整します。10%程度の追加で十分なことが多いです。"},{"question":"コントラストで暗すぎる写真を直せますか？","answer":"直せません。コントラストは幅を変えるだけで、レベルは変わりません。コントラストの高い暗い写真は、影が深くなっただけでやはり暗いです。まず明るさ調整ツールで明るくし、平たく見えるならコントラストを足します。"},{"question":"ポートレートにはプラスとマイナス、どちらのコントラストがいいですか？","answer":"たいていは5〜10%の小さなプラスの追加で、顔をはっきりさせつつ、きつくなりません。真昼の強い日差しで撮ったポートレートでは、-10%〜-20%のマイナスのコントラストで強い影をやわらげ、肌をきれいに見せられます。"},{"question":"コントラストを上げると色も強くなりますか？","answer":"はい。コントラストを上げると色が濃くなります。暗い部分がより暗く、明るい部分がより明るくなるからです。色が強すぎると感じたら、あとから彩度調整ツールで彩度を少し下げましょう。"},{"question":"ブラウザのツールで個人の写真のコントラストを調整しても安全ですか？","answer":"はい、安全です。処理はすべてブラウザの中で行われ、サーバーにアップロードされることはありません。書き出すときにEXIFの位置情報も取り除かれます。別のコントラストの値を試したい場合は、元ファイルを残しておきましょう。"}];
